(()=>{const run=document.querySelector("#run"),copy=document.querySelector("#copy"),result=document.querySelector("#result"),status=document.querySelector("#status");let report="";if(["localhost","127.0.0.1","[::1]"].includes(location.hostname)){run.disabled=true;status.textContent="本地预览不测试生产入口。发布后，请在发生漏记的设备与网络上运行此页。"}async function check(url,post=false){const controller=new AbortController,timer=setTimeout(()=>controller.abort(),6e3),start=performance.now();try{const response=await fetch(url,{method:post?"POST":"GET",mode:"cors",credentials:"omit",cache:"no-store",redirect:"error",referrerPolicy:"no-referrer",signal:controller.signal,...post?{headers:{"Content-Type":"text/plain;charset=UTF-8"},body:JSON.stringify({event:"page_view",page:"/analytics-check.html",context:"connection-check"})}:{}});const type=response.headers.get("content-type")||"";const data=type.includes("application/json")?await response.json():null;const recognized=data?.service==="jingtao-anonymous-collector"||data?.version==="observatory-v2";return{success:!!(response.ok&&data?.ok&&recognized),http_status:response.status,milliseconds:Math.round(performance.now()-start),version:data?.version||null,country:data?.country||null,browser:data?.browser||null,os:data?.os||null,note:!response.ok?"服务返回错误状态。":!data?"收到非 JSON 页面；可能是登录页面、挑战页面或旧配置。":!recognized?"响应不是当前采集协议。":"连接与服务绑定校验通过，未写入事件。"}}catch(error){return{success:false,milliseconds:Math.round(performance.now()-start),failure:error.name==="AbortError"?"timeout":"network_or_cors",note:error.name==="AbortError"?"6 秒内未完成响应。":"请求失败：浏览器无法仅凭此结果区分 DNS、路由、跨域、扩展或重定向。"}}finally{clearTimeout(timer)}}run.addEventListener("click",async()=>{run.disabled=true;copy.disabled=true;result.hidden=true;status.textContent="分别检查健康页与事件路径…";const endpoints=window.ANONYMOUS_ANALYTICS_ENDPOINTS||[],checks=[];for(const endpoint of endpoints){const postURL=new URL(endpoint);postURL.searchParams.set("check","1");const[health,post]=await Promise.all([check(new URL("/health",endpoint)),check(postURL,true)]);checks.push({endpoint,health,post,success:post.success,note:post.success?health.success?"两条路径均可连接。":"事件路径可连接，但健康页失败；不要因此判断事件采集失败。":"真正的事件路径未通过校验，不能据此断言国家识别有误。"})}report=JSON.stringify({checked_at:new Date().toISOString(),frontend_release:document.querySelector('meta[name="site-release"]')?.content||null,network:document.querySelector("#network").value,configured_endpoints:endpoints.length,checks,meaning:"检查不写入数据；通过仅证明采集路径与 binding 可用，实际入库仍需在 Events 核对正常页面访问。"},null,2);result.textContent=report;result.hidden=false;run.disabled=false;copy.disabled=false;status.textContent=checks.some(c=>c.success)?"至少一个事件入口连接成功；仍需核对真实 page_view。":"事件入口未通过检查，结果如下。"});copy.addEventListener("click",async()=>{try{await navigator.clipboard.writeText(report);status.textContent="结果已复制。"}catch{status.textContent="请手动复制下方结果。"}})})();
